from pathlib import Path
import io, zipfile, gzip, base64
import pandas as pd
import numpy as np
import streamlit as st

st.set_page_config(page_title="V6.9 Ateşleme Derin Karşılaştırma",page_icon="🔥",layout="wide")
st.title("🔥 V6.9 — ATEŞLEME KAPISI V1 / DERİN KARŞILAŞTIRMA")
st.success("ZERO-UPLOAD — V6.7 walk-forward sonuçları app içine gömülü. Dosya yükleme YOK.")
st.caption("Kapı değiştirilmez. 161 sinyaldeki 152 doğru ile 9 yanlış; gün, saat, WF blok, karakter, eşleşme seviyesi, güven ve gerçek hareket üzerinden karşılaştırılır.")

DATA_B64=""""""
STRONG={
"COALESCE_EXPAND|HIGH|DOWN2P|UP2P",
"EXPAND_FRAGMENT|HIGH|UP1|UP2P",
"COALESCE_EXPAND|HIGH|FLAT|UP2P",
"COALESCE_EXPAND|HIGH|DOWN1|UP2P",
"COALESCE_EXPAND|HIGH|DOWN1|UP1"}
VETO={7,11,23}

@st.cache_data
def load_data():
    return pd.read_csv(io.BytesIO(gzip.decompress(base64.b64decode(DATA_B64))))

def gate_data(df):
    x=df.copy()
    x["hour"]=x.time.astype(str).str[:2].astype(int)
    m=(x.predicted_motion.astype(str)!="SUS")&(x.confidence.astype(float)>=.80)&x.expert_character.isin(STRONG)&(~x.hour.isin(VETO))
    g=x[m].copy()
    g["result"]=np.where(g.correct.astype(int)==1,"DOGRU","YANLIS")
    g["confidence_pct"]=(g.confidence*100).round(2)
    return g

def grp(g,cols):
    t=(g.groupby(cols,dropna=False).agg(
        signals=("draw_no","count"),
        correct=("correct","sum"),
        avg_confidence=("confidence","mean"),
        avg_history=("history_events","mean")
    ).reset_index())
    t["wrong"]=t.signals-t.correct
    t["accuracy"]=(t.correct/t.signals).round(4)
    return t.sort_values(["accuracy","signals"],ascending=[True,False])

df=load_data()
g=gate_data(df)
good=g[g.correct==1].copy()
bad=g[g.correct==0].copy()

st.metric("Dondurulmuş sinyal",len(g))
c1,c2,c3=st.columns(3)
c1.metric("Doğru",len(good))
c2.metric("Yanlış",len(bad))
c3.metric("Başarı",f"{g.correct.mean()*100:.2f}%")

st.subheader("1 — 9 YANLIŞ OLAYIN TAM LİSTESİ")
wrong_cols=["wf_block","draw_no","date","time","expert_character","match_level","history_events","predicted_motion","actual_motion","confidence_pct"]
st.dataframe(bad[wrong_cols].sort_values(["date","time"]),use_container_width=True,hide_index=True)

st.subheader("2 — GÜN GÜN KIRILMA")
by_day=grp(g,["date"])
st.dataframe(by_day,use_container_width=True,hide_index=True)

st.subheader("3 — SAAT BAZINDA KIRILMA")
by_hour=grp(g,["hour"])
st.dataframe(by_hour,use_container_width=True,hide_index=True)

st.subheader("4 — WALK-FORWARD BLOK İSTİKRARI")
by_wf=grp(g,["wf_block"])
st.dataframe(by_wf,use_container_width=True,hide_index=True)

st.subheader("5 — UZMAN KARAKTERİ")
by_char=grp(g,["expert_character"])
st.dataframe(by_char,use_container_width=True,hide_index=True)

st.subheader("6 — EŞLEŞME SEVİYESİ")
by_match=grp(g,["match_level"])
st.dataframe(by_match,use_container_width=True,hide_index=True)

st.subheader("7 — TAHMİN EDİLEN HAREKET")
by_pred=grp(g,["predicted_motion"])
st.dataframe(by_pred,use_container_width=True,hide_index=True)

st.subheader("8 — DOĞRU / YANLIŞ PROFİL FARKI")
profile=pd.DataFrame([
{"group":"DOGRU","n":len(good),"avg_confidence":good.confidence.mean(),"median_confidence":good.confidence.median(),"avg_history_events":good.history_events.mean(),"median_history_events":good.history_events.median()},
{"group":"YANLIS","n":len(bad),"avg_confidence":bad.confidence.mean(),"median_confidence":bad.confidence.median(),"avg_history_events":bad.history_events.mean(),"median_history_events":bad.history_events.median()}
])
st.dataframe(profile,use_container_width=True,hide_index=True)

st.subheader("9 — YANLIŞLARIN YOĞUNLAŞTIĞI KESİŞİMLER")
cross=grp(g,["expert_character","hour"])
cross_bad=cross[cross.wrong>0]
st.dataframe(cross_bad,use_container_width=True,hide_index=True)

st.warning("Bu ekran yeni veto üretmez. 9 yanlıştan görülen desenler yalnız ADAY açıklamadır; yeni kural yapılacaksa ayrı, görülmemiş kronolojik blokta test edilmelidir.")

bio=io.BytesIO()
with zipfile.ZipFile(bio,"w",zipfile.ZIP_DEFLATED) as z:
    z.writestr("00_MANIFEST.txt","V6.9 ZERO-UPLOAD ATEŞLEME KAPISI V1 DERIN KARSILASTIRMA\nKapı sabit: confidence>=0.80 + 5 karakter + 07/11/23 veto + SUS yok.\nYeni veto optimize edilmez.\n")
    z.writestr("01_GATE_161_EVENTS.csv",g.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("02_WRONG_9_EVENTS.csv",bad.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("03_CORRECT_152_EVENTS.csv",good.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("04_BY_DAY.csv",by_day.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("05_BY_HOUR.csv",by_hour.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("06_BY_WF_BLOCK.csv",by_wf.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("07_BY_CHARACTER.csv",by_char.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("08_BY_MATCH_LEVEL.csv",by_match.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("09_BY_PREDICTED_MOTION.csv",by_pred.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("10_GOOD_VS_BAD_PROFILE.csv",profile.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("11_CHARACTER_HOUR_CROSS_WRONG.csv",cross_bad.to_csv(index=False).encode("utf-8-sig"))
st.download_button("⬇️ V6.9 DERİN KARŞILAŞTIRMA — TEK ZIP",bio.getvalue(),"HIZLI_ON_V6_9_ATESLEME_DERIN_KARSILASTIRMA.zip","application/zip",use_container_width=True)
